const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const mode=location.pathname.endsWith('/accounts')?'accounts':'approvals';let rows=[];
function labelStatus(s){const labels={pending:'승인 대기',approved:'승인 완료',rejected:'반려',suspended:'사용중지'};return `<span class="status ${esc(s||'pending')}">${esc(labels[s]||s||'-')}</span>`}
function setup(){const approval=mode==='approvals';document.title=(approval?'회원가입 승인':'협력사 계정 관리')+' | Hniruja EHS';$('pageTitle').textContent=approval?'회원가입 승인':'협력사 계정 관리';$('pageCopy').textContent=approval?'가입 신청을 검토하고 승인 또는 반려합니다.':'등록된 협력사 담당자 계정의 상태를 관리합니다.';$('panelTitle').textContent=approval?'승인 대기 회원':'전체 협력사 계정';$('approvalTab').classList.toggle('active',approval);$('accountTab').classList.toggle('active',!approval)}
function renderSummary(){const states=['pending','approved','rejected','suspended'];document.querySelectorAll('#summary b').forEach((el,i)=>el.textContent=rows.filter(r=>r.approval_status===states[i]).length)}
function actionButtons(row){const id=esc(row.id),name=esc(row.name||row.email||'선택한 회원');let html='';if(row.approval_status!=='approved')html+=`<button class="btn primary" type="button" data-action="approve" data-id="${id}" data-name="${name}">승인</button>`;if(row.approval_status==='pending')html+=`<button class="btn danger" type="button" data-action="reject" data-id="${id}" data-name="${name}">반려</button>`;if(row.approval_status==='approved')html+=`<button class="btn danger" type="button" data-action="suspend" data-id="${id}" data-name="${name}">사용중지</button>`;return html||'-'}
function render(){renderSummary();const q=$('searchInput').value.trim().toLowerCase();let list=mode==='approvals'?rows.filter(r=>r.approval_status==='pending'):rows.slice();if(q)list=list.filter(r=>[r.company_name,r.name,r.position,r.email,r.phone].some(v=>String(v||'').toLowerCase().includes(q)));$('tableBox').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>회사명</th><th>이름</th><th>직급</th><th>연락처</th><th>이메일</th><th>가입일</th>${mode==='accounts'?'<th>상태</th>':''}<th>처리</th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.company_name||'-')}</td><td><b>${esc(r.name||'-')}</b></td><td>${esc(r.position||'-')}</td><td>${esc(r.phone||'-')}</td><td>${esc(r.email||'-')}</td><td>${esc(String(r.created_at||'-').slice(0,10))}</td>${mode==='accounts'?`<td>${labelStatus(r.approval_status)}</td>`:''}<td><div class="actions">${actionButtons(r)}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">'+(mode==='approvals'?'승인 대기 회원이 없습니다.':'조건에 맞는 계정이 없습니다.')+'</div>';document.querySelectorAll('[data-action]').forEach(btn=>btn.onclick=()=>accountAction(btn.dataset.id,btn.dataset.action,btn.dataset.name))}
async function load(){ $('tableBox').className='loading';$('tableBox').textContent='계정 정보를 불러오는 중...';try{const d=await window.EHSApi.request('/api/admin/registrations',{ehsNoCache:true});rows=d.registrations||[];$('tableBox').className='';render()}catch(e){$('tableBox').className='error';$('tableBox').textContent=window.EHSApi?.describe?window.EHSApi.describe(e):e.message}}
async function accountAction(id,action,name){const title={approve:'승인',reject:'반려',suspend:'사용중지'}[action];if(!confirm(`${name} 계정을 ${title}하시겠습니까?`))return;let reason='';if(action==='reject'){reason=prompt('반려 사유를 입력하세요.','')||'';if(!reason.trim())return}try{await window.EHSApi.request(`/api/admin/registrations/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({action,reason:reason.trim()})});await load()}catch(e){alert(window.EHSApi?.describe?window.EHSApi.describe(e):e.message)}}
(async()=>{setup();try{const user=await window.EHSAuth.requireUser();if(user.role!=='admin'){location.replace('/home');return}window.__EHS_PAGE_USER=user;document.dispatchEvent(new CustomEvent('ehs:user-ready',{detail:user}));$('searchInput').addEventListener('input',render);$('refreshBtn').onclick=load;await load()}catch(e){if(e?.status!==401){$('tableBox').className='error';$('tableBox').textContent=e.message||'관리자 화면을 열 수 없습니다.'}}})();
